CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('USER','ADMIN','RESTAURANT')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS restaurants(id SERIAL PRIMARY KEY,name TEXT NOT NULL,address TEXT NOT NULL,cuisine TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS menu_items(id SERIAL PRIMARY KEY,restaurant_id INT NOT NULL REFERENCES restaurants(id) ON DELETE CASCADE,name TEXT NOT NULL,price NUMERIC(10,2) NOT NULL CHECK(price>0),available BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS orders(id SERIAL PRIMARY KEY,user_id INT NOT NULL REFERENCES users(id),restaurant_id INT NOT NULL REFERENCES restaurants(id),status TEXT NOT NULL CHECK(status IN ('CREATED','PAID','PREPARING','OUT_FOR_DELIVERY','DELIVERED','CANCELLED')),total_amount NUMERIC(10,2) NOT NULL CHECK(total_amount>=0),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_items(id SERIAL PRIMARY KEY,order_id INT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,menu_item_id INT NOT NULL REFERENCES menu_items(id),quantity INT NOT NULL CHECK(quantity>0));
CREATE TABLE IF NOT EXISTS payments(id SERIAL PRIMARY KEY,order_id INT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,amount NUMERIC(10,2) NOT NULL,status TEXT NOT NULL,method TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications(id SERIAL PRIMARY KEY,order_id INT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,channel TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_orders_user_created ON orders(user_id,created_at DESC); CREATE INDEX IF NOT EXISTS idx_menu_restaurant ON menu_items(restaurant_id); CREATE INDEX IF NOT EXISTS idx_notifications_order ON notifications(order_id);
